INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist im Klassendiagramm entscheidend, um Beziehungen zwischen Klassen darzustellen?', 2, '[{"text": "Linien (Assoziationen)", "correct": true, "because": "Zeigen Verbindungen zwischen Klassen"}, {"text": "Farbe der Klassen", "correct": false, "because": "Kein Einfluss auf Struktur"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Klassendiagramm immer dynamisch?', 1, '[{"text": "Nein", "correct": true, "because": "Es zeigt statische Strukturen"}, {"text": "Ja", "correct": false, "because": "Dynamik in anderen Diagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für ein Klassendiagramm wichtig?', 5, '[{"text": "Klassen", "correct": true, "because": "Grundbausteine der Struktur"}, {"text": "Attribute", "correct": true, "because": "Definieren Eigenschaften"}, {"text": "Hintergrundfarbe", "correct": false, "because": "Kein funktionaler Aspekt"}, {"text": "Methoden", "correct": true, "because": "Beschreiben Verhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Klassendiagramme richtig? a) Sie zeigen die Struktur eines Systems. b) Sie beschreiben den Ablauf von Prozessen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Struktur, nicht Ablauf"}, {"text": "Beides stimmt", "correct": false, "because": "Ablauf in Sequenzdiagrammen"}, {"text": "Nur b) stimmt", "correct": false, "because": "Struktur ist zentral"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Erstellung eines Klassendiagramms ignorieren?', 2, '[{"text": "Beziehungen zwischen Klassen", "correct": false, "because": "Wichtig für Struktur"}, {"text": "Farbe der Diagrammelemente", "correct": true, "because": "Kein Einfluss auf Modell"}, {"text": "Sichtbarkeit von Attributen", "correct": false, "because": "Entscheidend für Zugriff"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist im Klassendiagramm entscheidend, um Beziehungen zwischen Klassen darzustellen?', 2, '[{"text": "Assoziationen", "correct": true, "because": "Zeigen Verbindungen zwischen Klassen"}, {"text": "Farbe der Linien", "correct": false, "because": "Kein Einfluss auf Bedeutung"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Klassendiagramm immer dynamisch?', 1, '[{"text": "Nein", "correct": true, "because": "Es ist statisch, zeigt Struktur"}, {"text": "Ja", "correct": false, "because": "Dynamik in anderen Diagrammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für ein Klassendiagramm wichtig?', 5, '[{"text": "Klassen", "correct": true, "because": "Grundbausteine"}, {"text": "Attribute", "correct": true, "because": "Definieren Eigenschaften"}, {"text": "Hintergrundfarbe", "correct": false, "because": "Kein Einfluss"}, {"text": "Methoden", "correct": true, "because": "Definieren Verhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Klassendiagramme richtig? a) Sie zeigen die Struktur von Klassen. b) Sie beschreiben den Programmablauf.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Struktur, nicht Ablauf"}, {"text": "Beides stimmt", "correct": false, "because": "Ablauf ist dynamisch"}, {"text": "Nur b) stimmt", "correct": false, "because": "Struktur ist zentral"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du im Klassendiagramm ignorieren?', 2, '[{"text": "Klassenattribute", "correct": false, "because": "Wichtig für Struktur"}, {"text": "Diagrammlayout", "correct": true, "because": "Ästhetik, keine Funktion"}, {"text": "Vererbung", "correct": false, "because": "Zeigt Beziehungen"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Klassendiagramm entscheidend, um Beziehungen zwischen Klassen darzustellen?', 2, '[{"text": "Beziehungen (z.B. Assoziation)", "correct": true, "because": "Zeigt Verbindungen"}, {"text": "Farbe der Linien", "correct": false, "because": "Kein Einfluss auf Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Klassendiagramm immer eine vollständige Implementierung?', 1, '[{"text": "Nein", "correct": true, "because": "Es ist ein Entwurfsmodell"}, {"text": "Ja", "correct": false, "because": "Kein ausführbarer Code"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für ein Klassendiagramm wichtig?', 5, '[{"text": "Klassen", "correct": true, "because": "Grundbausteine des Diagramms"}, {"text": "Attribute", "correct": true, "because": "Definieren Eigenschaften"}, {"text": "Schriftgröße", "correct": false, "because": "Nur Darstellung"}, {"text": "Methoden", "correct": true, "because": "Beschreiben Verhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Klassendiagramme richtig? a) Eine Klasse kann mehrere Beziehungen haben. b) Klassendiagramme zeigen nur Klassen ohne Methoden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Beziehungen vielfältig, Methoden üblich"}, {"text": "Beides stimmt", "correct": false, "because": "Methoden sind enthalten"}, {"text": "Nur b) stimmt", "correct": false, "because": "Beziehungen sind möglich"}, {"text": "Beides falsch", "correct": false, "because": "Aussage a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du bei der Erstellung eines Klassendiagramms ignorieren?', 2, '[{"text": "Attribute", "correct": false, "because": "Wichtig für Eigenschaften"}, {"text": "Farbe der Klassenbox", "correct": true, "because": "Nur Darstellung, keine Funktion"}, {"text": "Beziehungen", "correct": false, "because": "Entscheidend für Struktur"}]');
